BL: $dbQuery = 'select foldername from vtiger_attachmentsfolder where foldername=?';
BL: $dbQuery = 'select foldername from vtiger_attachmentsfolder where foldername=? and folderid!=?';
BL: $sql = 'insert into vtiger_attachmentsfolder (folderid,foldername,description,createdby,sequence) values (?,?,?,?,?)';
BL: $sql = 'update vtiger_attachmentsfolder set foldername=? where folderid= ?';
BL: $sql = 'update vtiger_attachmentsfolder set foldername=?, description=? where folderid= ?';
